index df95e1b..5dda4d7 100644
--- a/io/io.cpp
+++ b/io/io.cpp
@@ -772,9 +772,21 @@ extern "C" bool c_vcedbg(natl testid, natl testlen, natb* testdata)
 /// Parte C++ della primitiva vcenew()
 extern "C" bool c_vcenew()
 {
-/// @todo Scrivere il corpo della primitiva vcenew()
-// ( SOLUZIONE 2025-01-27
-//   SOLUZIONE 2025-01-27 )
+	natl pid = getpid();
+	sem_wait(ce.mutex);
+	if (ce.vces[pid] != nullptr) {
+		sem_signal(ce.mutex);
+		abort_p();
+	}
+	vce_des *v = new vce_des;
+	if (!vce_des_init(v)) {
+		delete v;
+		sem_signal(ce.mutex);
+		return false;
+	}
+	ce.vces[pid] = v;
+	sem_signal(ce.mutex);
+	return true;
 }

 /// Parte C++ della primitiva vcewrite()
@@ -814,9 +826,46 @@ extern "C" void c_vcewrite(char c)
 /// Processo esterno associato alla periferica CE
 extern "C" void estern_ce(natq)
 {
-/// @todo Scrivere il corpo del processo esterno
-// ( SOLUZIONE 2025-01-27
-//   SOLUZIONE 2025-01-27 )
+	natl current = -1;
+	for (;;) {
+		natq ev = evget();
+		sem_wait(ce.mutex);
+		if (ev > 0 && ev < MAX_PROC) {
+			vce_des *v = ce.vces[ev];
+			if (v) {
+				v->terminated = true;
+				if (v->n == 0 && v->waiting) {
+					sem_signal(v->sync);
+				}
+				if (v->n == 0) {
+					ce.vces[ev] = nullptr;
+					delete v;
+				}
+			}
+		} else if (ev == 0) {
+			ce.busy = false;
+		}
+		if (!ce.busy) {
+			vce_des *v = vce_des_next(current);
+			if (v) {
+				natl c = vce_des_read(v);
+				if (c != 0xFFFFFFFF) {
+					outputb(static_cast<char>(c), ce.iTBR);
+					ce.busy = true;
+					if (v->waiting) {
+						sem_signal(v->sync);
+						v->waiting = false;
+					}
+				}
+				if (v->n == 0 && v->terminated) {
+					ce.vces[current] = nullptr;
+					delete v;
+				}
+			}
+		}
+		sem_signal(ce.mutex);
+		wfi();
+	}
 }

